/bin/bash -c "python3 - <<'PY'
from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
uris=set()
for page in r.pages:
    for a in page.get('/Annots', []):
        action=a.get_object().get('/A', {})
        if action.get('/URI'): uris.add(str(action['/URI']))
print('Repository and resource links:')
for u in sorted(uris):
    if any(k in u.lower() for k in ('github','huggingface','zenodo','radar','dataset')): print(u)
print('Attachments:',list(r.attachments))
PY"
